            ("13", 2),
            ("24", 0),
            ("123456789", 5),
            ("111111111", 9),
            ("000000000", 0),
            ("97531", 5),
            ("86420", 0),
        ],
    )
    def test_parametrized_counts(self, s, expected_count):
        result = odd_count([s])
        assert result == build_expected([expected_count])

    def test_does_not_mutate_input_list(self):
        original = ['123', '456']
