import pytest

from solution import get_odd_collatz


def collatz_sequence(n):
    """Reference implementation used to derive expected results for random-ish inputs."""
    seq, x = [n], n
    while x != 1:
        x = x // 2 if x % 2 == 0 else x * 3 + 1
        seq.append(x)
    return seq


def expected_odd_sorted(n):
    return sorted(x for x in collatz_sequence(n) if x % 2 == 1)


class TestGetOddCollatzBasicCases:
    def test_n_equals_1(self):
        assert get_odd_collatz(1) == [1]

    def test_example_from_docstring(self):
        assert get_odd_collatz(5) == [1, 5]

    def test_n_equals_2(self):
        # Collatz(2) -> [2, 1]; odd numbers: [1]
        assert get_odd_collatz(2) == [1]

    def test_n_equals_4(self):
        # Collatz(4) -> [4, 2, 1]; odd numbers: [1]
        assert get_odd_collatz(4) == [1]

    def test_n_equals_3(self):
        # Collatz(3) -> [3, 10, 5, 16, 8, 4, 2, 1]; odd: 3, 5, 1
        assert get_odd_collatz(3) == [1, 3, 5]

    def test_n_equals_6(self):
        # Collatz(6) -> [6, 3, 10, 5, 16, 8, 4, 2, 1]; odd: 3, 5, 1
        assert get_odd_collatz(6) == [1, 3, 5]

    def test_n_equals_7(self):
        # Collatz(7) -> 7,22,11,34,17,52,26,13,40,20,10,5,16,8,4,2,1
        # odd numbers: 7,11,17,13,5,1
        assert get_odd_collatz(7) == sorted([7, 11, 17, 13, 5, 1])


class TestGetOddCollatzProperties:
    @pytest.mark.parametrize("n", list(range(1, 51)))
    def test_matches_reference_implementation(self, n):
        assert get_odd_collatz(n) == expected_odd_sorted(n)

