"""
Unit tests for split_words.

The function under test:

    def split_words(txt):
        whitespace = tuple(' \n\r\t')
        if any([x in txt for x in whitespace]): return txt.split()
        if "," in txt: return txt.split(",")
        cnt = 0
        for ch in txt:
            if ch.islower() and (ord(ch) - ord("a")) % 2 == 1: cnt += 1
        return cnt
"""

import pytest

from split_words_module import split_words


# ---------------------------------------------------------------------------
# Whitespace splitting (highest priority branch)
# ---------------------------------------------------------------------------

class TestWhitespaceSplit:
    def test_simple_space_separated_words(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words_space_separated(self):
        assert split_words("The quick brown fox") == ["The", "quick", "brown", "fox"]

    def test_tab_separated(self):
        assert split_words("Hello\tworld") == ["Hello", "world"]

    def test_newline_separated(self):
        assert split_words("Hello\nworld") == ["Hello", "world"]

    def test_carriage_return_separated(self):
        assert split_words("Hello\rworld") == ["Hello", "world"]

    def test_collapses_extra_whitespace_and_strips_ends(self):
        assert split_words("  Hello   world  ") == ["Hello", "world"]

    def test_mixed_whitespace_types(self):
        assert split_words("Hello \t\n world") == ["Hello", "world"]

    def test_whitespace_takes_priority_over_comma(self):
        # Contains both a comma and a space -> whitespace branch wins.
        assert split_words("Hello, world") == ["Hello,", "world"]

    def test_only_whitespace_returns_empty_list(self):
        assert split_words("   ") == []


# ---------------------------------------------------------------------------
# Comma splitting (second-priority branch)
# ---------------------------------------------------------------------------

class TestCommaSplit:
    def test_simple_comma_separated(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_multiple_commas(self):
        assert split_words("a,b,c") == ["a", "b", "c"]

    def test_comma_with_empty_fields(self):
        assert split_words("a,,b") == ["a", "", "b"]

    def test_leading_and_trailing_comma(self):
        assert split_words(",a,b,") == ["", "a", "b", ""]

    def test_only_comma_returns_two_empty_strings(self):
        assert split_words(",") == ["", ""]


# ---------------------------------------------------------------------------
# No whitespace, no comma -> count of lowercase letters at odd alphabet index
# ---------------------------------------------------------------------------

class TestOddLetterCount:
    def test_docstring_example(self):
        assert split_words("abcdef") == 3

    def test_empty_string_returns_zero(self):
        assert split_words("") == 0

    def test_all_uppercase_returns_zero(self):
        assert split_words("ABCDEF") == 0

    def test_digits_and_punctuation_only_returns_zero(self):
        assert split_words("12345!") == 0

    def test_mixed_case_counts_only_lowercase(self):
        # lowercase letters: a, b, c, d -> odd-indexed ones: b, d => 2
        assert split_words("aAbBcCdD") == 2

    def test_full_lowercase_alphabet(self):
        # odd-indexed letters: b d f h j l n p r t v x z -> 13 letters
        assert split_words("abcdefghijklmnopqrstuvwxyz") == 13

    def test_single_even_index_letter(self):
        assert split_words("a") == 0

    def test_single_odd_index_letter(self):
        assert split_words("b") == 1

    def test_repeated_odd_index_letters(self):
        assert split_words("bdbd") == 4

    def test_no_whitespace_no_comma_with_mixed_content(self):
        assert split_words("z9!") == 1


