    def test_index_not_multiple_of_3_or_4_unchanged(self):
        # indexes: 0(sq),1(unchanged),2(unchanged)
        assert sum_squares([2, 3, 4]) == 4 + 3 + 4  # 2**2 + 3 + 4

    def test_index4_is_cubed(self):
        # indexes 0..4: 0->sq,1->unchanged,2->unchanged,3->sq,4->cube
        lst = [1, 1, 1, 1, 2]
        expected = (1 ** 2) + 1 + 1 + (1 ** 2) + (2 ** 3)
        assert sum_squares(lst) == expected

    def test_index_multiple_of_both_3_and_4_is_squared_not_cubed(self):
        # index 12 is a multiple of both 3 and 4; squaring takes precedence
        lst = [0] * 12 + [3]
