            ("5/3", "3/5"),        # 5/3 * 3/5 = 1
            ("2/4", "2/1"),        # 2/4 * 2/1 = 1 (reduces cleanly)
            ("3/1", "4/1"),        # 3 * 4 = 12, whole
            ("10/2", "3/1"),       # 5 * 3 = 15, whole
            ("6/2", "1/3"),        # 3 * 1/3 = 1
            ("100/10", "1/5"),     # 10 * 1/5 = 2
            ("1/1000000", "1000000/1"),  # large numbers cancel exactly
        ],
    )
    def test_returns_true_for_whole_results(self, x, n):
        assert simplify(x, n) is True


class TestSimplifyFalseCases:
