    """Unit tests for truncate_number.

    truncate_number has no external collaborators (it only uses the
    built-in `int()` conversion), so no mocking/stubbing is required to
    achieve isolation here.
    """

    def test_docstring_example(self):
        assert truncate_number(3.5) == pytest.approx(0.5)

    def test_simple_decimal(self):
        assert truncate_number(1.25) == pytest.approx(0.25)

    def test_zero_decimal_part(self):
        # A whole-number float should truncate to exactly 0.0.
        assert truncate_number(5.0) == pytest.approx(0.0)

    def test_value_between_zero_and_one(self):
        # Integer part is 0, so result should equal the input itself.
        assert truncate_number(0.75) == pytest.approx(0.75)

    def test_value_just_above_zero(self):
        assert truncate_number(0.0001) == pytest.approx(0.0001)

    def test_large_number(self):
        assert truncate_number(12345.6789) == pytest.approx(0.6789)

    def test_small_fraction_near_next_integer(self):
        assert truncate_number(9.9999) == pytest.approx(0.9999)

    def test_result_is_always_less_than_one(self):
        result = truncate_number(42.987654321)
        assert 0 <= result < 1

    def test_zero_input(self):
        assert truncate_number(0.0) == pytest.approx(0.0)

    def test_return_type_is_float(self):
        result = truncate_number(7.42)
        assert isinstance(result, float)

    def test_repeated_calls_are_consistent(self):
        # Pure function: same input should always produce same output.
        first = truncate_number(2.71828)
        second = truncate_number(2.71828)
        assert first == second

    def test_precision_matches_manual_computation(self):
        number = 123.456
        expected = number - int(number)
        assert truncate_number(number) == pytest.approx(expected)

    def test_not_nan(self):
        assert not math.isnan(truncate_number(3.14))
