import pytest

from how_many_times import how_many_times


class TestBasicExamples:
    def test_empty_string_returns_zero(self):
        assert how_many_times('', 'a') == 0

    def test_all_same_characters(self):
        assert how_many_times('aaa', 'a') == 3

    def test_overlapping_substring(self):
        assert how_many_times('aaaa', 'aa') == 3


class TestNoMatches:
    def test_substring_not_present(self):
        assert how_many_times('hello', 'x') == 0

    def test_substring_longer_than_string(self):
        assert how_many_times('ab', 'abc') == 0

    def test_non_empty_substring_in_empty_string(self):
        assert how_many_times('', 'abc') == 0


class TestOverlappingOccurrences:
    def test_overlapping_pattern_abab(self):
        # positions: 0 'abab...', overlapping matches at 0 and 2
        assert how_many_times('ababa', 'aba') == 2

    def test_overlapping_repeated_pattern(self):
        assert how_many_times('aaaaa', 'aa') == 4

    def test_non_overlapping_natural_count(self):
        assert how_many_times('abcabcabc', 'abc') == 3


class TestSingleCharacterMatches:
    def test_single_char_substring_count(self):
        assert how_many_times('banana', 'a') == 3

    def test_single_char_substring_no_match(self):
        assert how_many_times('banana', 'z') == 0


class TestWholeStringMatch:
    def test_substring_equals_string(self):
        assert how_many_times('hello', 'hello') == 1

    def test_substring_equals_single_char_string(self):
        assert how_many_times('a', 'a') == 1


class TestEmptySubstring:
    def test_empty_substring_in_empty_string(self):
        assert how_many_times('', '') == 0

    def test_empty_substring_in_non_empty_string(self):
        # every index startswith('') is True, so result equals len(string)
        assert how_many_times('abc', '') == 3

    def test_empty_substring_in_single_char_string(self):
        assert how_many_times('a', '') == 1


class TestCaseSensitivity:
    def test_case_sensitive_no_match(self):
        assert how_many_times('AAA', 'a') == 0

    def test_case_sensitive_match(self):
        assert how_many_times('AAA', 'A') == 3

    def test_mixed_case_partial_match(self):
        assert how_many_times('AaAaAa', 'Aa') == 3


class TestSpecialCharacters:
    def test_substring_with_spaces(self):
        assert how_many_times('a a a a', 'a ') == 3

    def test_substring_with_punctuation(self):
        assert how_many_times('a.b.a.b.a.', 'a.') == 3

    def test_substring_treated_literally_not_regex(self):
        # '.' should be matched literally, not as a regex wildcard
        assert how_many_times('a.a.a', '.') == 2
        assert how_many_times('axaxa', '.') == 0


class TestLongerExamples:
    def test_repeated_word(self):
        assert how_many_times('the quick the quick the quick fox', 'the quick') == 3

    def test_dna_like_sequence_overlap(self):
        assert how_many_times('ATATATAT', 'ATAT') == 3

    def test_no_overlap_possible(self):
        assert how_many_times('xyz', 'xyzxyz') == 0


