        assert by_length(arr) == [
            "Eight", "Five", "Four", "Three", "Two", "Two", "One", "One"
        ]

    def test_empty_array(self):
        assert by_length([]) == []

    def test_strange_numbers_ignored(self):
        assert by_length([1, -1, 55]) == ["One"]


class TestByLengthSortingAndReversing:
    def test_already_sorted_ascending(self):
        assert by_length([1, 2, 3, 4, 5]) == ["Five", "Four", "Three", "Two", "One"]

    def test_already_sorted_descending(self):
        assert by_length([5, 4, 3, 2, 1]) == ["Five", "Four", "Three", "Two", "One"]

    def test_unsorted_array(self):
        assert by_length([9, 3, 7, 1, 5]) == ["Nine", "Seven", "Five", "Three", "One"]

    def test_duplicates_preserved_in_order(self):
        assert by_length([3, 3, 3]) == ["Three", "Three", "Three"]

    def test_single_element(self):
        assert by_length([7]) == ["Seven"]


class TestByLengthAllDigits:
    def test_all_digits_one_to_nine(self):
        arr = [9, 8, 7, 6, 5, 4, 3, 2, 1]
        expected = [
            "Nine", "Eight", "Seven", "Six", "Five",
            "Four", "Three", "Two", "One",
        ]
        assert by_length(arr) == expected

    def test_all_digits_shuffled(self):
        arr = [4, 8, 1, 9, 2, 6, 3, 7, 5]
        expected = [
            "Nine", "Eight", "Seven", "Six", "Five",
            "Four", "Three", "Two", "One",
        ]
        assert by_length(arr) == expected

