def reference_odd_collatz(n):
    """Independent reference implementation used as an oracle for property-based checks.

    Builds the full Collatz sequence for `n` (ending in 1) and returns the sorted
    list of its odd members, mirroring the documented behaviour of get_odd_collatz.
    """
    sequence = [n]
    x = n
    while x != 1:
        x = x // 2 if x % 2 == 0 else 3 * x + 1
        sequence.append(x)
    return sorted({v for v in sequence if v % 2 == 1})


