        assert len(result) == 3

    def test_mixed_odd_and_even_length(self):
        assert sorted_list_sum(["ab", "a", "aaa", "cd"]) == ["ab", "cd"]

    def test_empty_string_has_even_length_and_is_kept(self):
        assert sorted_list_sum(["", "a", "ab"]) == ["", "ab"]


