        # Uppercase letters have lower ordinal values than lowercase in ASCII,
        # so they sort first for equal-length strings.
        result = sorted_list_sum(["AB", "ab", "Ab", "aB"])
        assert result == ["AB", "Ab", "aB", "ab"]


