"""Unit tests for the fibfib sequence function."""

from module import fibfib

KNOWN_VALUES = {
    0: 0,
    1: 0,
    2: 1,
    3: 1,
    4: 2,
    5: 4,
    6: 7,
    7: 13,
    8: 24,
    9: 44,
    10: 81,
}

MAX_REFERENCE_N = 20


def reference_fibfib(n: int) -> int:
    """Compute fibfib recursively with memoization for cross-checking results."""
    cache = {0: 0, 1: 0, 2: 1}

    def helper(value: int) -> int:
        if value in cache:
            return cache[value]
        result = helper(value - 1) + helper(value - 2) + helper(value - 3)
        cache[value] = result
        return result

    return helper(n)


def test_base_case_zero() -> None:
    assert fibfib(0) == 0


def test_base_case_one() -> None:
    assert fibfib(1) == 0


def test_base_case_two() -> None:
    assert fibfib(2) == 1


def test_docstring_example_five() -> None:
    assert fibfib(5) == 4


def test_docstring_example_eight() -> None:
    assert fibfib(8) == 24


def test_known_values_table() -> None:
    for n, expected in sorted(KNOWN_VALUES.items()):
        assert fibfib(n) == expected


def test_matches_reference_implementation() -> None:
    for n in range(MAX_REFERENCE_N + 1):
        assert fibfib(n) == reference_fibfib(n)


def test_recurrence_relation_holds() -> None:
    for n in range(3, MAX_REFERENCE_N + 1):
        assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


def test_return_type_is_int() -> None:
    for n in range(MAX_REFERENCE_N + 1):
        assert isinstance(fibfib(n), int)


def test_sequence_is_non_decreasing_after_index_two() -> None:
    values = [fibfib(n) for n in range(2, MAX_REFERENCE_N + 1)]
    assert all(current <= following for current, following in zip(values, values[1:]))


def test_large_n_computes_without_error() -> None:
    result = fibfib(100)
    assert isinstance(result, int)
    assert result > 0

