"""Unit tests for the sum_squares function."""

import pytest

from solution import sum_squares


def test_empty_list() -> None:
    assert sum_squares([]) == 0


def test_example_small_list() -> None:
    assert sum_squares([1, 2, 3]) == 6


def test_example_negative_numbers() -> None:
    assert sum_squares([-1, -5, 2, -1, -5]) == -126


def test_single_element_index_zero_is_squared() -> None:
    # Index 0 is a multiple of 3, so the entry should be squared.
    assert sum_squares([4]) == 16


def test_negative_single_element_index_zero_is_squared() -> None:
    assert sum_squares([-3]) == 9


def test_index_multiple_of_four_not_three_is_cubed() -> None:
    # Indexes: 0 -> squared, 1,2,3 -> unchanged, 4 -> cubed.
    lst = [1, 1, 1, 1, 2]
    expected = (1 ** 2) + 1 + 1 + 1 + (2 ** 3)
    assert sum_squares(lst) == expected


def test_index_that_is_multiple_of_both_three_and_four_is_squared() -> None:
    # Index 12 is a multiple of both 3 and 4; squaring takes precedence.
    lst = [0] * 12 + [5]
    assert sum_squares(lst) == 25


def test_indexes_not_multiples_of_three_or_four_are_unchanged() -> None:
    lst = [0, 7, 9, 0, 0]
    # Index 1 and 2 are untouched; indexes 0, 3, 4 are squared or cubed.
    expected = (0 ** 2) + 7 + 9 + (0 ** 2) + (0 ** 3)
    assert sum_squares(lst) == expected


def test_all_zeros() -> None:
    assert sum_squares([0, 0, 0, 0, 0, 0, 0, 0]) == 0


@pytest.mark.parametrize(
    "lst, expected",
    [
        ([1], 1),
        ([1, 2], 3),
        ([1, 2, 3, 4], 26),
        ([2, 3, 4, 5, 6, 7, 8, 9], 4193),
    ],
)
def test_parametrized_cases(lst: list, expected: int) -> None:
    assert sum_squares(lst) == expected


def test_does_not_mutate_input_list() -> None:
    original = [1, 2, 3, 4, 5]
    lst = list(original)
    sum_squares(lst)
    assert lst == original


def test_large_list_performance_and_correctness() -> None:
    lst = list(range(1, 13))
    total = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total += value ** 2
        elif index % 4 == 0:
            total += value ** 3
        else:
            total += value
    assert sum_squares(lst) == total
